// Offline support. precache.js (generated by scripts/build-precache.mjs) defines APP_VERSION (a hash of every
// precached file) and PRECACHE (the file list), so any change to the app installs a new worker.
importScripts("precache.js");

const CACHE = `truco-${self.APP_VERSION}`;
const NETWORK_TIMEOUT_MS = 3000;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(self.PRECACHE.map((path) => new Request(new URL(path, self.registration.scope), { cache: "reload" }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n.startsWith("truco-") && n !== CACHE).map((n) => caches.delete(n)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(networkFirst(request));
});

function fetchWithTimeout(request) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), NETWORK_TIMEOUT_MS);
  return fetch(request, { signal: controller.signal }).finally(() => clearTimeout(timer));
}

/** Fresh when online, cached when offline or slow (a bar with bad signal). */
async function networkFirst(request) {
  const cache = await caches.open(CACHE);
  try {
    const response = await fetchWithTimeout(request);
    if (response.ok && response.type === "basic") {
      await cache.put(request, response.clone());
      return response;
    }
  } catch {
    // offline or timed out: fall through to the cache
  }
  const hit = await cache.match(request, { ignoreSearch: request.mode === "navigate" });
  if (hit) return hit;
  if (request.mode === "navigate") {
    const shell = await cache.match(new URL("index.html", self.registration.scope));
    if (shell) return shell;
  }
  return Response.error();
}
